56	export async function recordToolCallInteractions(
57	  config: Config,
58	  toolCalls: CompletedToolCall[],
59	): Promise<void> {
60	  // Only send interaction events for responses that contain function calls.
61	  if (toolCalls.length === 0) {
62	    return;
63	  }
64	
65	  try {
66	    const server = getCodeAssistServer(config);
67	    if (!server) {
68	      return;
69	    }
70	
71	    const interaction = summarizeToolCalls(toolCalls);
72	    if (interaction) {
73	      await server.recordConversationInteraction(interaction);
74	    }
75	  } catch (error: unknown) {
76	    debugLogger.warn(
77	      `Error recording tool call interactions: ${getErrorMessage(error)}`,
78	    );
79	  }
80	}
