82	export function createConversationOffered(
83	  response: GenerateContentResponse,
84	  traceId: string,
85	  signal: AbortSignal | undefined,
86	  streamingLatency: StreamingLatency,
87	): ConversationOffered | undefined {
88	  // Only send conversation offered events for responses that contain function
89	  // calls. Non-function call events don't represent user actionable
90	  // 'suggestions'.
91	  if ((response.functionCalls?.length || 0) === 0) {
92	    return;
93	  }
94	
95	  const actionStatus = getStatusFromResponse(response, signal);
96	
97	  return {
98	    citationCount: String(getCitations(response).length),
99	    includedCode: includesCode(response),
100	    status: actionStatus,
101	    traceId,
102	    streamingLatency,
103	    isAgentic: true,
104	    initiationMethod: InitiationMethod.COMMAND,
105	  };
106	}
107	
108	function summarizeToolCalls(
109	  toolCalls: CompletedToolCall[],
110	): ConversationInteraction | undefined {
111	  let acceptedToolCalls = 0;
112	  let actionStatus = undefined;
113	  let traceId = undefined;
114	
115	  // Treat file edits as ACCEPT_FILE and everything else as unknown.
116	  let isEdit = false;
117	  let acceptedLines = 0;
118	  let removedLines = 0;
119	
120	  // Iterate the tool calls and summarize them into a single conversation
121	  // interaction so that the ConversationOffered and ConversationInteraction
122	  // events are 1:1 in telemetry.
123	  for (const toolCall of toolCalls) {
124	    traceId ||= toolCall.request.traceId;
125	
126	    // If any tool call is canceled, we treat the entire interaction as canceled.
127	    if (toolCall.status === 'cancelled') {
128	      actionStatus = ActionStatus.ACTION_STATUS_CANCELLED;
129	      break;
130	    }
131	
132	    // If any tool call encounters an error, we treat the entire interaction as
133	    // having errored.
134	    if (toolCall.status === 'error') {
135	      actionStatus = ActionStatus.ACTION_STATUS_ERROR_UNKNOWN;
136	      break;
137	    }
138	
139	    // Record if the tool call was accepted.
140	    if (toolCall.outcome !== ToolConfirmationOutcome.Cancel) {
141	      acceptedToolCalls++;
142	
143	      // Edits are ACCEPT_FILE, everything else is UNKNOWN.
144	      if (EDIT_TOOL_NAMES.has(toolCall.request.name)) {
145	        isEdit = true;
146	
147	        if (toolCall.status === 'success') {
148	          const fileDiff = getFileDiffFromResultDisplay(
149	            toolCall.response.resultDisplay,
150	          );
151	          if (fileDiff?.diffStat) {
152	            const lines = computeModelAddedAndRemovedLines(fileDiff.diffStat);
153	            acceptedLines += lines.addedLines;
154	            removedLines += lines.removedLines;
155	          }
156	        }
157	      }
158	    }
159	  }
160	
161	  // Only file interaction telemetry if 100% of the tool calls were accepted.
162	  return traceId && acceptedToolCalls / toolCalls.length >= 1
163	    ? createConversationInteraction(
164	        traceId,
165	        actionStatus || ActionStatus.ACTION_STATUS_NO_ERROR,
166	        isEdit
167	          ? ConversationInteractionInteraction.ACCEPT_FILE
168	          : ConversationInteractionInteraction.UNKNOWN,
169	        isEdit ? String(acceptedLines) : undefined,
170	        isEdit ? String(removedLines) : undefined,
171	      )
172	    : undefined;
173	}
174	
175	function createConversationInteraction(
176	  traceId: string,
177	  status: ActionStatus,
178	  interaction: ConversationInteractionInteraction,
179	  acceptedLines?: string,
180	  removedLines?: string,
181	): ConversationInteraction {
182	  return {
183	    traceId,
184	    status,
185	    interaction,
186	    acceptedLines,
187	    removedLines,
188	    isAgentic: true,
189	  };
190	}
191	function includesCode(resp: GenerateContentResponse): boolean {
192	  if (!resp.candidates) {
193	    return false;
194	  }
195	  for (const candidate of resp.candidates) {
196	    if (!candidate.content || !candidate.content.parts) {
197	      continue;
198	    }
199	    for (const part of candidate.content.parts) {
200	      if ('text' in part && part?.text?.includes('```')) {
201	        return true;
202	      }
203	    }
204	  }
205	  return false;
206	}
207	
208	function getStatusFromResponse(
209	  response: GenerateContentResponse,
210	  signal: AbortSignal | undefined,
211	): ActionStatus {
212	  if (signal?.aborted) {
213	    return ActionStatus.ACTION_STATUS_CANCELLED;
214	  }
215	
216	  if (hasError(response)) {
217	    return ActionStatus.ACTION_STATUS_ERROR_UNKNOWN;
218	  }
219	
220	  if ((response.candidates?.length ?? 0) <= 0) {
221	    return ActionStatus.ACTION_STATUS_EMPTY;
222	  }
223	
224	  return ActionStatus.ACTION_STATUS_NO_ERROR;
225	}
226	
227	export function formatProtoJsonDuration(milliseconds: number): string {
228	  return `${milliseconds / 1000}s`;
229	}
230	
231	function hasError(response: GenerateContentResponse): boolean {
232	  // Non-OK SDK results should be considered an error.
233	  if (
234	    response.sdkHttpResponse &&
235	    !response.sdkHttpResponse?.responseInternal?.ok
236	  ) {
237	    return true;
238	  }
239	
240	  for (const candidate of response.candidates || []) {
241	    // Treat sanitization, SPII, recitation, and forbidden terms as an error.
242	    if (
243	      candidate.finishReason &&
244	      candidate.finishReason !== FinishReason.STOP &&
245	      candidate.finishReason !== FinishReason.MAX_TOKENS
246	    ) {
247	      return true;
248	    }
249	  }
